import React, { useState } from "react";
import MemoryPhoto from "./MemoryPhoto";
import PhotoLightbox from "./PhotoLightbox";

/**
 * MemoryGallery:
 * The centerpiece photographic journey.
 * Renders two continuous, seamless 60fps GPU-accelerated floating streams:
 * - Row 1: Photos floating smoothly LEFT → RIGHT
 * - Row 2: Photos floating smoothly RIGHT → LEFT
 * 
 * Clicking any photo opens the full-screen centered PhotoLightbox modal.
 */
export const MemoryGallery = ({ config, memories }) => {
  const [isRow1Paused, setIsRow1Paused] = useState(false);
  const [isRow2Paused, setIsRow2Paused] = useState(false);
  const [selectedPhotoIndex, setSelectedPhotoIndex] = useState(null);

  // Divide the 15 memories across two rows:
  // Row 1: 8 memories, Row 2: 7 memories
  const row1Memories = memories.slice(0, 8);
  const row2Memories = memories.slice(8, 15);

  // Duplicate items to guarantee infinite seamless wrap
  const seamlessRow1 = [...row1Memories, ...row1Memories];
  const seamlessRow2 = [...row2Memories, ...row2Memories];

  const handleOpenPhoto = (memory) => {
    const originalIndex = memories.findIndex((m) => m.id === memory.id);
    setSelectedPhotoIndex(originalIndex !== -1 ? originalIndex : 0);
  };

  const handleCloseLightbox = () => {
    setSelectedPhotoIndex(null);
  };

  const handlePrevPhoto = () => {
    setSelectedPhotoIndex((prev) =>
      prev === null ? 0 : (prev - 1 + memories.length) % memories.length
    );
  };

  const handleNextPhoto = () => {
    setSelectedPhotoIndex((prev) =>
      prev === null ? 0 : (prev + 1) % memories.length
    );
  };

  return (
    <section id="memories" className="memories-section" aria-label="Photo Memories Journey">
      {/* Section Header */}
      <div className="memories-header">
        <span className="memories-eyebrow">PHOTO JOURNEY</span>
        <h2 className="memories-title">{config.memoriesHeader.title}</h2>
        <p className="memories-subtitle">{config.memoriesHeader.subtitle}</p>
        <span className="memories-hint" aria-hidden="true">
          Click any photograph to view in full size • Hover to pause
        </span>
      </div>

      {/* Stream Container with edge vignette masking */}
      <div className="stream-viewport">
        {/* ROW 1: Floating LEFT → RIGHT */}
        <div
          className={`stream-row stream-row-1 ${isRow1Paused ? "stream-paused" : ""}`}
          aria-label="Memories row moving left to right"
        >
          <div className="stream-track stream-track-ltr">
            {seamlessRow1.map((mem, index) => (
              <MemoryPhoto
                key={`r1-${mem.id}-${index}`}
                memory={mem}
                index={index}
                onHoverChange={setIsRow1Paused}
                onClick={handleOpenPhoto}
              />
            ))}
          </div>
        </div>

        {/* ROW 2: Floating RIGHT → LEFT */}
        <div
          className={`stream-row stream-row-2 ${isRow2Paused ? "stream-paused" : ""}`}
          aria-label="Memories row moving right to left"
        >
          <div className="stream-track stream-track-rtl">
            {seamlessRow2.map((mem, index) => (
              <MemoryPhoto
                key={`r2-${mem.id}-${index}`}
                memory={mem}
                index={index}
                onHoverChange={setIsRow2Paused}
                onClick={handleOpenPhoto}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Full-Screen Centered Lightbox Modal */}
      {selectedPhotoIndex !== null && (
        <PhotoLightbox
          memory={memories[selectedPhotoIndex]}
          currentIndex={selectedPhotoIndex}
          totalCount={memories.length}
          onClose={handleCloseLightbox}
          onPrev={handlePrevPhoto}
          onNext={handleNextPhoto}
        />
      )}
    </section>
  );
};

export default MemoryGallery;
